/**
 * SEO 组件
 *
 * 多语言：hrefLang 传 'en' / 'de'；canonical 与 og:url 自动带对应语言前缀。
 * 不传 hrefLang 时按英文处理（向后兼容所有既有调用点）。
 *
 * @author 恒哥
 */
import React from 'react';
import { Helmet } from 'react-helmet';
import { useStaticQuery, graphql } from 'gatsby';
import {
  PRODUCT_NAME,
  PRODUCT_NAME_FULL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_INSTALL_PAGE_PATH,
  SITE_URL,
} from '../../constants/brand';
import { DEFAULT_LOCALE, LOCALES, isLocalizedPath, localePath, resolveLocale } from '../../i18n/config';

export default function SEO({
  title,
  description,
  image,
  pathname,
  ogTitle,
  noindex = false,
  hrefLang = DEFAULT_LOCALE,
  /**
   * 是否输出 `SoftwareApplication` 结构化数据（默认 true，见下方 softwareSchema）。
   *
   * 🔴 **品牌层页面必须传 `softwareApp={false}`**（2026-10-12 加）：这段 schema 描述的是
   *    **Whaleal Cart 这个 Shopify 应用**（`operatingSystem: 'Shopify'`、
   *    `downloadUrl` 指向 App Store）。放在 /messaging、/integrations、/about 这类
   *    品牌/另一条产品线的页面上，等于向搜索引擎声明「这个页面讲的是一个 Shopify 应用」——
   *    是**事实错误**，且会污染 Rich Results。
   *    默认 true 是刻意保持既有页面行为不变（Cart 相关页占多数，且它们确实该带）。
   */
  softwareApp = true,
  /**
   * FAQPage 结构化数据。传 `[{ q, a }]` —— **与页面正文用的是同一个数组**。
   *
   * 🔴 2026-10-14 新增。此前只有 `/faq/` 在自己文件里手写这段 JSON-LD，而
   *    `/features/`、`/industries/`、`/use-cases/`、`/compare/`、`/solutions/`
   *    这些族页**每页都有自己的 `faq` 数组、都在正文里渲染问答，却一条 schema 都没输出**
   *    —— 搜索引擎只看到一堆普通文本。收进组件 = 一处实现、所有页共用；页面只需把
   *    **那份已经在渲染的数组**传进来，所以不存在「schema 里的答案页面上没有」的漂移。
   */
  faqs = [],
  /**
   * BreadcrumbList 结构化数据。传 `[{ name, path }]`，`path` 是**站点内绝对路径**
   * （`/features/` 这种写法，不带域、不带语言前缀，与 canonical 同源）。
   *
   * ℹ️ 2026-10-14 起页面上的**视觉面包屑已全部移除**（用户要求），但本结构化数据
   *    **保留**：它描述的是真实的 URL 层级（Home > 族 > 页），是 SEO 资产，且不在
   *    页面上渲染 —— 删它没有任何视觉收益、只会丢搜索结果里的层级展示。
   *    因此约束从「与页面面包屑一致」改为：**层级必须与该页的真实 URL 路径一致**，
   *    不得编造不存在的层级（中间层无独立 URL 时只给 name，见下方 map）。
   */
  breadcrumbs = [],
  /** `og:type`。文章类页面（guide / help）传 `'article'`，其余保持默认。 */
  ogType = 'website',
}) {
  const { site } = useStaticQuery(
    graphql`
      query {
        site {
          siteMetadata {
            title
            description
            siteUrl
            author
          }
        }
      }
    `
  );

  const { title: defaultTitle, description: defaultDescription, siteUrl } = site.siteMetadata;

  // pathname 传的是**英文视角**的路径（页面里写的都是 /pricing/ 这种），
  // 统一在这里加语言前缀 —— 页面作者不必关心自己在哪个语言版本里。
  const { basePath } = resolveLocale(pathname || '/');
  const localeCfg = LOCALES[hrefLang] || LOCALES[DEFAULT_LOCALE];
  const localizedPath = localePath(basePath, hrefLang);

  // 🔴 站点后缀 ` | Whaleal` 只在两个条件同时满足时才追加（2026-10-14）：
  //    ① 标题本体里还没出现品牌名 —— `Whaleal Cart` 也算。此前 solutions 数据自带
  //       `| Whaleal Cart`，组件又无条件追加，实测产物出现过
  //       `... | Whaleal Cart | Whaleal`（/solutions/abandoned-cart-sms/ 全长 97 字符）。
  //    ② 加上后仍在 Google 桌面端 ~60 字符的显示上限内 —— 超限时宁可少一个后缀，
  //       也不让标题正文被截断（正文才是关键词所在）。
  //    判据只在这一处实现；数据文件里的 metaTitle 一律不带后缀（见各 data/*.js）。
  const TITLE_DISPLAY_LIMIT = 60;
  const siteSuffix = ` | ${defaultTitle}`;
  const buildTitle = (raw) => {
    if (!raw) return defaultTitle;
    if (raw.includes(defaultTitle)) return raw;
    return raw.length + siteSuffix.length <= TITLE_DISPLAY_LIMIT ? raw + siteSuffix : raw;
  };

  const seo = {
    title: buildTitle(title),
    description: description || defaultDescription,
    url: `${siteUrl}${localizedPath}`,
    ogTitle: ogTitle || title || defaultTitle, // og:title 使用原始标题，不包含后缀
  };

  const htmlLang = localeCfg.htmlLang;
  const ogLocale = localeCfg.ogLocale;
  // og:locale:alternate 是逗号分隔的其它语言版本
  const alternateLocales = Object.keys(LOCALES)
    .filter((c) => c !== hrefLang)
    .map((c) => LOCALES[c].ogLocale)
    .join(',');
  // 🔴 **hreflang 只对「真的有多语言版本」的页面输出**（2026-10-12 修）。
  //
  //    此前无条件按 LOCALES 全量输出三条 —— 对 LOCALIZED_PAGES 里的页面正确，
  //    但对**非本地化页**（/about/、/customers/、/privacy/、/terms/、/gdpr/、
  //    cart-rescue/*，以及此后新增的一批英文-only 页）是错的：localePath() 在这类
  //    路径上刻意不加前缀，于是三条 hreflang 的 href **完全相同**，实测产物为
  //      /about/  →  en:/about/  de:/about/  fr:/about/  x-default:/about/
  //    意思变成「德语版和法语版就是这个英文页」。这是**互指关系中的自相矛盾**：
  //    既声明存在 de/fr 版本，又把它指向英文 URL。Google 的处置是整组 hreflang
  //    判为无效（连正确的那条 en 一起丢掉），比不写更糟。
  //
  //    判据用 isLocalizedPath —— 与 gatsby-node 生成路由、localePath 决定是否加
  //    前缀读的是**同一份 LOCALIZED_PAGES 清单**，三处不会漂移。
  //    ⇒ 非本地化页只留 canonical（+ 下面的 x-default 也一并省掉，没有 alternate
  //      时 x-default 无参照物，留着只是噪音）。
  //
  // 🔴 **2026-10-12 补第二道判据：只有一种语言时一条 hreflang 都不输出**。
  //    主站已改为英文单语（见 i18n/config.js 的范围决策），`LOCALES` 只剩 `en`。
  //    若只保留原判据，LOCALIZED_PAGES 里的页面会输出**一条 hreflang="en" 指向自己**
  //    加一条 x-default 指向自己 —— 前者是自我指涉（无对照物），后者更明确是错的：
  //    x-default 的语义是「没有匹配语言时的兜底版本」，只有一种语言时不存在
  //    「匹配不上」的情形。两条都属于噪音，去掉更干净。
  const hasTranslations = Object.keys(LOCALES).length > 1 && isLocalizedPath(basePath);
  const hreflangLinks = hasTranslations
    ? Object.keys(LOCALES).map((c) => ({
        hreflang: LOCALES[c].htmlLang,
        href: `${siteUrl}${localePath(basePath, c)}`,
      }))
    : [];
  const defaultPathForDefaultLocale = localePath(basePath, DEFAULT_LOCALE);

  // 🔴 社交卡片图（2026-10-14 重做）：此前用的是 512×512 的 favicon，却声明
  //    `twitter:card=summary_large_image`（期望 ~1200×630 的横图）—— 方图配大卡片，
  //    在 X/LinkedIn/Slack 上会被裁切或缩成小图。现在是一张专门的 1200×630 品牌卡
  //    （static/images/og-default.png，由仓库内的生成脚本产出）。
  //    宽高写进常量而不是散落在 JSX 字面量里 —— 同一规范值两处实现必然漂移。
  const OG_DEFAULT_PATH = '/images/og-default.png';
  const OG_WIDTH = '1200';
  const OG_HEIGHT = '630';
  const ogImage = image || `${siteUrl}${OG_DEFAULT_PATH}`;
  // JSON-LD 里的 Organization/WebSite logo 用方形 favicon（schema.org 期望的就是
  // logo 而不是社交卡）—— 与 og:image 是两个用途，别混用同一张图。
  const logoImage = `${siteUrl}/favicon/favicon.png`;
  const robotsContent = noindex
    ? 'noindex, nofollow'
    : 'index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1';

  // JSON-LD 结构化数据
  // 🔴 2026-10-16：Organization 块已**移出**本组件、改写到 `src/html.js` 的 HTML 壳层，
  //    以保证每个页面的静态 HTML 里必定存在（不再依赖页面渲染 <SEO />）。
  //    这里只保留页面级 schema（SoftwareApplication / WebSite / FAQPage / BreadcrumbList）。

  const softwareSchema = softwareApp ? JSON.stringify({
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    "name": PRODUCT_NAME,
    "alternateName": PRODUCT_NAME_FULL,
    "applicationCategory": "BusinessApplication",
    "operatingSystem": "Shopify",
    "offers": {
      "@type": "Offer",
      "price": "0",
      "priceCurrency": "USD",
      "availability": "https://schema.org/InStock"
    },
    "description": seo.description,
    "url": `${SITE_URL}${SHOPIFY_INSTALL_PAGE_PATH}`,
    "downloadUrl": SHOPIFY_APP_STORE_URL,
    "author": {
      "@type": "Organization",
      "name": "Whaleal",
      "url": siteUrl
    }
  }) : null;

  const websiteSchema = pathname === '/' ? JSON.stringify({
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    name: 'Whaleal',
    url: siteUrl,
    description: defaultDescription,
    publisher: {
      '@type': 'Organization',
      name: 'Whaleal',
      logo: logoImage,
    },
  }) : null;

  // FAQPage —— 只在真的渲染了问答的页面输出。`faqs` 与页面正文是**同一个数组**，
  // 所以不会出现「结构化数据里的答案页面上根本没有」这种漂移。
  const faqSchema =
    faqs && faqs.length > 0
      ? JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'FAQPage',
          mainEntity: faqs.map(({ q, a }) => ({
            '@type': 'Question',
            name: q,
            acceptedAnswer: { '@type': 'Answer', text: a },
          })),
        })
      : null;

  // BreadcrumbList —— 层级必须与该页的**真实 URL 路径**一致（视觉面包屑已于
  // 2026-10-14 移除，见上方 breadcrumbs prop 的说明）；编造层级 = 给搜索引擎
  // 一份站上不存在的路径。
  const breadcrumbSchema =
    breadcrumbs && breadcrumbs.length > 0
      ? JSON.stringify({
          '@context': 'https://schema.org',
          '@type': 'BreadcrumbList',
          itemListElement: breadcrumbs.map((b, i) => ({
            '@type': 'ListItem',
            position: i + 1,
            name: b.name,
            // 中间层（如 help 的分类）没有独立 URL —— 只给 name 不给 item，
            // 比编一个假 URL 好（Google 允许层级项无 item）。
            ...(b.path ? { item: `${siteUrl}${b.path}` } : {}),
          })),
        })
      : null;

  return (
    <Helmet>
      <html lang={htmlLang} />
      <title>{seo.title}</title>
      <meta name="description" content={seo.description} />
      <meta name="robots" content={robotsContent} />
      <meta name="googlebot" content={robotsContent} />
      <meta name="theme-color" content="#1a3a5c" />
      <meta property="og:locale" content={ogLocale} />
      {/* og:locale:alternate 与 hreflang 同判据 —— 非本地化页没有别的语言版本，
          留着会向社交平台声明一个不存在的 de/fr 版本。 */}
      {hasTranslations && (
        <meta property="og:locale:alternate" content={alternateLocales} />
      )}
      <link rel="icon" type="image/svg+xml" href="/favicon/favicon.svg" />
      <link rel="icon" type="image/png" sizes="48x48" href="/favicon/favicon-48.png" />
      <link rel="icon" type="image/png" sizes="32x32" href="/favicon/favicon-32.png" />
      <link rel="apple-touch-icon" sizes="180x180" href="/favicon/apple-touch-icon.png" />
      <link rel="manifest" href="/site.webmanifest" />
      <meta property="og:title" content={seo.ogTitle} />
      <meta property="og:description" content={seo.description} />
      <meta property="og:url" content={seo.url} />
      <meta property="og:site_name" content="Whaleal" />
      <meta property="og:type" content={ogType} />
      <meta property="og:image" content={ogImage} />
      <meta property="og:image:width" content={OG_WIDTH} />
      <meta property="og:image:height" content={OG_HEIGHT} />
      <meta property="og:image:alt" content="Whaleal — Shopify cart recovery and messaging infrastructure" />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={seo.title} />
      <meta name="twitter:description" content={seo.description} />
      <meta name="twitter:image" content={ogImage} />
      {!noindex && <link rel="canonical" href={seo.url} />}
      {/* hreflang：告诉搜索引擎同一页面的各语言版本，避免多语言互相「抢」排名。
          英文保持原路径（prefix 为空），德语带 /de 前缀。x-default 指向英文。
          🔴 仅本地化页输出 —— 判据与理由见上方 hasTranslations 的说明。 */}
      {hreflangLinks.map((l) => (
        <link key={l.hreflang} rel="alternate" hrefLang={l.hreflang} href={l.href} />
      ))}
      {hasTranslations && (
        <link rel="alternate" hrefLang="x-default" href={`${siteUrl}${defaultPathForDefaultLocale}`} />
      )}
      {/* Organization JSON-LD 已移至 html.js 壳层（每页静态 HTML 必有，详见该文件）。 */}
      {softwareSchema && <script type="application/ld+json">{softwareSchema}</script>}
      {websiteSchema && <script type="application/ld+json">{websiteSchema}</script>}
      {faqSchema && <script type="application/ld+json">{faqSchema}</script>}
      {breadcrumbSchema && <script type="application/ld+json">{breadcrumbSchema}</script>}
    </Helmet>
  );
}

